
package com.vola.tv
import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.vola.tv.databinding.ItemCardBinding
class LiveAdapter(val items:List<Channel>, val onClick:(Channel)->Unit): RecyclerView.Adapter<LiveAdapter.H>(){ class H(val b:ItemCardBinding): RecyclerView.ViewHolder(b.root); override fun onCreateViewHolder(p:ViewGroup,t:Int)=H(ItemCardBinding.inflate(LayoutInflater.from(p.context),p,false)); override fun getItemCount()=items.size; override fun onBindViewHolder(h:H,pos:Int){ val item=items[pos]; h.b.title.text=item.name; h.b.sub.text="قناة حية"; if(item.icon.isNotEmpty()) Glide.with(h.itemView).load(item.icon).into(h.b.poster); h.itemView.setOnClickListener{ onClick(item) } } }
class VodAdapter(val items:List<Vod>, val onClick:(Vod)->Unit): RecyclerView.Adapter<VodAdapter.H>(){ class H(val b:ItemCardBinding): RecyclerView.ViewHolder(b.root); override fun onCreateViewHolder(p:ViewGroup,t:Int)=H(ItemCardBinding.inflate(LayoutInflater.from(p.context),p,false)); override fun getItemCount()=items.size; override fun onBindViewHolder(h:H,pos:Int){ val item=items[pos]; h.b.title.text=item.name; h.b.sub.text="فيلم - "+item.rating; if(item.poster.isNotEmpty()) Glide.with(h.itemView).load(item.poster).into(h.b.poster); h.itemView.setOnClickListener{ onClick(item) } } }
class SeriesAdapter(val items:List<SeriesItem>, val onClick:(SeriesItem)->Unit): RecyclerView.Adapter<SeriesAdapter.H>(){ class H(val b:ItemCardBinding): RecyclerView.ViewHolder(b.root); override fun onCreateViewHolder(p:ViewGroup,t:Int)=H(ItemCardBinding.inflate(LayoutInflater.from(p.context),p,false)); override fun getItemCount()=items.size; override fun onBindViewHolder(h:H,pos:Int){ val item=items[pos]; h.b.title.text=item.name; h.b.sub.text="مسلسل"; if(item.poster.isNotEmpty()) Glide.with(h.itemView).load(item.poster).into(h.b.poster); h.itemView.setOnClickListener{ onClick(item) } } }
class FavAdapter(val items:List<Triple<String,String,String>>, val onClick:(Triple<String,String,String>)->Unit): RecyclerView.Adapter<FavAdapter.H>(){ class H(val b:ItemCardBinding): RecyclerView.ViewHolder(b.root); override fun onCreateViewHolder(p:ViewGroup,t:Int)=H(ItemCardBinding.inflate(LayoutInflater.from(p.context),p,false)); override fun getItemCount()=items.size; override fun onBindViewHolder(h:H,pos:Int){ val it=items[pos]; h.b.title.text=it.second; h.b.sub.text="مفضل"; if(it.third.isNotEmpty()) Glide.with(h.itemView).load(it.third).into(h.b.poster) } }
class ContinueAdapter(val items:List<String>, val onClick:(String)->Unit): RecyclerView.Adapter<ContinueAdapter.H>(){ class H(val b:ItemCardBinding): RecyclerView.ViewHolder(b.root); override fun onCreateViewHolder(p:ViewGroup,t:Int)=H(ItemCardBinding.inflate(LayoutInflater.from(p.context),p,false)); override fun getItemCount()=items.size; override fun onBindViewHolder(h:H,pos:Int){ val parts=items[pos].split("|"); h.b.title.text=if(parts.size>1) parts[1] else "متابعة"; h.b.sub.text="أكمل المشاهدة"; if(parts.size>2 && parts[2].isNotEmpty()) Glide.with(h.itemView).load(parts[2]).into(h.b.poster) } }
